cc.Class({
    extends: require("BunnyGirl_symbol"),

    properties: {
        
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init:function(idx,node){
        this._topAniNode = node
        this.SetSymbolIdx(idx);

        this.ShowRandomSymbol()
    },

    //播放win效果但又没有spin动画。自己写一个tween的action
    //先填写个默认的。
    playWinTweenAction(){
        let nodeAnimation = this.node.getComponent(cc.Animation)
        nodeAnimation.play("bigSymbolWin")
    },
    //停止tween类型的action动画
    stopWinTweenAction(){
        let nodeAnimation = this.node.getComponent(cc.Animation)
        nodeAnimation.play("bigSymbolIdel")
    },

    GetRandomCfg:function(){
        let cfg = cc.vv.gameData.getGameCfg()
        return cfg.cardmapfree
    },

    //设置框体的父节点
    //根据层级可能需要重写
    GetKuangShowParent:function(){
        return this._topAniNode
    },

    playWinAnimation(){
        if(this._state === "win"){
            return
        }
        this._super()
    },

    // update (dt) {},
});
