let unlockNum = [8,12,16,20]
cc.Class({
    extends: cc.Component,

    properties: {
        _reels:[],  //所有列
        _jushu:null,  //剩余局数
        _lockRoot:null,  //解锁节点
        _winCoinRoot:null,  //赢钱节点
        _success:null,  //promise成功回调
        _roundList:[],
        _lockList:[],
        _moveReelLastIdx:0,
        _moveIdxList:[],  //当前可转动列
        _cfg:null,
        _col:0,
        _row:0,
        _canStopReel:false,
        _coin:0,
        _bonusNum:0,
        _spinCnt:0,
        _gameInfo:null,  //服务器下发的51消息
        _unlockRow:4,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        for (let i = 1; i < 41; i++) {
            let reel = cc.find("slots/reels/reel"+i,this.node)
            let scp = reel.addComponent("BunnyGirl_bonusReel")
            scp.Init(i-1,1,cc.find("slots/top_ani",this.node))
            this._reels.push(scp)
        }
        for (let i = 1; i < 4; i++) {
            let round = cc.find("jushu/round"+i,this.node)
            this._roundList.push(round)
        }
        for (let i = 1; i < 5; i++) {
            let lockNode = cc.find("luckRoot/luckNode"+i,this.node)
            this._lockList.push(lockNode)
        }
        this._winCoinRoot = cc.find("winCoinRoot",this.node)
        this._cfg = cc.vv.gameData.getGameCfg()
        this._col = this._cfg.col
        this._row = 8
    },

    start () {

    },

    awaitTime(time){
        return new Promise((success, failed)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },

    showBonusGame(data,isReconnect){
        return new Promise(async (success,failed)=>{
            Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.music_Mermaid_RespinBG)
            this._success = success
            this._coin = 0
            cc.vv.gameData.getManage()._isInBonus = true
            this.node.active = true
            await this.awaitTime(0)
            this._winCoinRoot.active = false
            cc.find("Canvas/safe_node/spr_bg_free").active = true
            this._moveIdxList = []
            for (let i = 1; i < 41; i++) {
                const reel = this._reels[i-1]
                if(reel){
                    reel._symbols[0].InitSymbol()
                    reel._symbols[1].InitSymbol()
                }
                this._moveIdxList.push(i)
            }
            for (let i = 0; i < data.bonusIdxs.length; i++) {
                const idx = data.bonusIdxs[i]
                let reel = this._reels[idx-1]
                if(reel){
                    reel.setResult(data.bonusItems[i])
                }
                for (let j = 0; j < this._moveIdxList.length; j++) {
                    if(idx === this._moveIdxList[j]){
                        this._moveIdxList.splice(j,1)
                        break
                    }
                }
            }
            this._unlockRow = 4
            for (let i = 0; i < data.unlockInfo.length; i++) {
                if(data.unlockInfo[i] === 0){
                    this._unlockRow++
                }
            }
            let bonusNum = 0
            for (let i = 0; i < data.bonusIdxs.length; i++) {
                const idx = data.bonusIdxs[i]
                let row = this._row - Math.floor((idx -1)/this._col) -1
                if(row < this._unlockRow){
                    bonusNum++
                }
            }
            this.initUnLockNum(bonusNum)
            this.updateSpinTime(data.spinCnt)
            if(!isReconnect){  //等一下过场动画
                await this.awaitTime(1)
            }
            this.autoSpin()
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("bounsGame")
        })
    },

    autoSpin(){
        this.unschedule(this.StartMove)
        this.scheduleOnce(this.StartMove,this._cfg.autoModelDelay)
    },

    async hide(){
        await cc.vv.gameData.getQiePing().showQiePing1(()=>{
            this.node.active = false
            cc.find("Canvas/safe_node/spr_bg_free").active = false
        })
        await cc.vv.gameData.GetSlotsScript().ShowWinCoin(cc.vv.gameData.GetBottomScript().getCurrentWin(),cc.vv.gameData.GetBottomScript().getCurrentWin(),true)
        this.exitBonusGame()
    },

    async OnSpinEnd(){
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1")
        if(this._gameInfo.result.idxs.length > 0){
            let bonusNum = 0
            for (let i = 0; i < this._gameInfo.result.idxs.length; i++) {
                const idx = this._gameInfo.result.idxs[i]
                let row = this._row - Math.floor((idx -1)/this._col) -1
                if(row < this._unlockRow){
                    bonusNum++
                }
            }
            this.updateUnLockNum(this._bonusNum + bonusNum)
            this.updateSpinTime(this._gameInfo.bonusGame.spinCnt)
            await this.awaitTime(1)
        }
        if(this._gameInfo.bonusGame.isEnd){  //结束游戏
            await this.ShowResult(this._gameInfo.bonusGame.bonusIdxs,this._gameInfo.bonusGame.bonusItems)
            this.hide()
        }else {
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("bounsGame")
            this.autoSpin()
        }
    },

    exitBonusGame(){
        cc.vv.gameData.getManage()._isInBonus = false
        Global.SlotsSoundMgr.playNormalBgm(true)
        if(this._success){
            this._success()
            this._success = null
        }
    },

    updateSpinTime(time){
        this._spinCnt = time
        for (let i = 0; i < this._roundList.length; i++) {
            const round = this._roundList[i]
            if(time === (i+1)){
                cc.find("select",round).active = true
            }else{
                cc.find("select",round).active = false
            }
        }
    },

    unlockRow(row){
        return new Promise(async (success,failed)=>{
            let lockNode = this._lockList[row-1]
            if(lockNode){
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Mermaid_respin_unlock)
                let lockNodeAni = lockNode.getComponent(cc.Animation)
                lockNodeAni.play("jiesuo")
                lockNodeAni.on("finished",()=>{
                    lockNodeAni.off("finished")
                    lockNode.active = false
                    lizi.active = false
                    success()
                })
                await this.awaitTime(0.5)
                let lizi = cc.find("jiesuo_lizi",lockNode)
                lizi.active = true
                lizi.getComponent(cc.ParticleSystem).resetSystem()
            }
        })
    },

    OnMsgSpin(data){
        this._gameInfo = data
        let cards = []
        for (let i = 0; i < 40; i++) {
            let randIdx = Global.random(2,this._cfg.randomSymbols.length)
            let randVal = this._cfg.randomSymbols[randIdx-1]
            let randData = null
            for (let j = 0; j < data.result.idxs.length; j++) {
                if((i + 1) === data.result.idxs[j]){
                    randVal = 3
                    randData = data.result.items[j]
                    break
                }
            }
            if(randVal === 3){
                for (let j = 0; j < this._moveIdxList.length; j++) {
                    if((i+1) === this._moveIdxList[j]){
                        this._moveIdxList.splice(j,1)
                        break
                    }
                }
            }
            cards.push(randVal)
            const reel = this._reels[i]
            reel.SetResult([{sid:randVal,data:randData}])
        }
        this.SetReelStateInfo(cards)
        this._canStopReel = true
    },

    SetReelStateInfo:function(cards){
        if (!this._cfg.reelStateInfo) {
            return;
        }

        for (let info of this._cfg.reelStateInfo) {
            let stateInfo = Global.copy(info);
            stateInfo.isStop = false
            stateInfo.isAnt = false

            for(let i = 0; i < cards.length; i++){
                let item = this._reels[i]
                let val = cards[i]
                stateInfo.isStop = false
                stateInfo.isAnt = false
                stateInfo.isStop = stateInfo.id.includes(val)
                item.AddReelStateInfo(Global.copy(stateInfo))
            }
        }
    },

    initUnLockNum(curNum){
        this._bonusNum = curNum
        for (let i = 0; i < this._lockList.length; i++) {
            const num = unlockNum[i]
            const lockNode = this._lockList[i]
            if(lockNode){
                if(num - curNum > 0){  //更新数字
                    cc.find("num",lockNode).getComponent(cc.Label).string = num - curNum
                    lockNode.active = true
                    lockNode.opacity = 255
                }else{
                    cc.find("num",lockNode).getComponent(cc.Label).string = 0
                    if(lockNode.active){
                        lockNode.active = false
                    }
                }
            }
        }
    },

    /*
    更新锁定节点，这里因为解锁之后，珍珠的数量可能会变多所以写个递归判断解锁一层后如果满足下一层解锁需求
    继续解锁下一层
     */
    updateUnLockNum(curNum){
        let tempUnlockRow = 4
        for (let i = 0; i < this._lockList.length; i++) {
            const num = unlockNum[i]
            if(num - curNum <= 0){  //更新数字
                tempUnlockRow++
            }
        }
        if(tempUnlockRow > this._unlockRow){
            this._unlockRow = tempUnlockRow
            let bonusNum = 0
            for (let i = 0; i < this._gameInfo.bonusGame.bonusIdxs.length; i++) {
                const idx = this._gameInfo.bonusGame.bonusIdxs[i]
                let row = this._row - Math.floor((idx -1)/this._col) -1
                if(row < this._unlockRow){
                    bonusNum++
                }
            }
            this.updateUnLockNum(bonusNum)
        }else{
            this._bonusNum = curNum
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Mermaid_RsBar_rest)
            for (let i = 0; i < this._lockList.length; i++) {
                const num = unlockNum[i]
                const lockNode = this._lockList[i]
                if(lockNode){
                    if(num - curNum > 0){  //更新数字
                        cc.find("num",lockNode).getComponent(cc.Label).string = num - curNum
                    }else{
                        cc.find("num",lockNode).getComponent(cc.Label).string = 0
                        if(lockNode.active){
                            this.unlockRow(i+1)
                        }
                    }
                }
            }
        }
    },

    //重置解锁节点
    resetLockNode(){
        for (let i = 0; i < this._lockList.length; i++) {
            const lockNode = this._lockList[i]
            lockNode.active = true
            lockNode.opacity = 255
            cc.find("liang",lockNode).active = false
        }
    },

    //开始转动
    StartMove(){
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1")
        this.unschedule(this.StartMove)
        this._moveReelLastIdx = 0
        let sortArray = (a,b)=>{
            let acol = (a - 1) % this._col
            let bcol = (b - 1) % this._col
            if(acol == bcol){
                return a - b
            }else{
                return acol - bcol
            }
        }
        this._moveIdxList.sort(sortArray)
        for (let i = 0; i < this._moveIdxList.length; i++) {
            const idx = this._moveIdxList[i] - 1
            let reel = this._reels[idx]
            if(reel){
                reel.StartMove()
                this._moveReelLastIdx = idx
            }
        }
        this._stopTime = cc.vv.gameData.GetSlotsScript().GetStopTime()
        this._canStopReel = false
        this._roundSpineTime = 0
        this.updateSpinTime(this._spinCnt - 1)
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.uid = Global.playerData.uid;
        req.gameid = cc.vv.gameData._gameId;
        req.data = {};
        req.data.rtype = 1;
        cc.vv.NetManager.send(req);
    },

    GetLastMoveReelIdx(){
        return this._moveReelLastIdx
    },

    CanStopSlot(){
        return this._canStopReel
    },

    update (dt) {
        if(this._stopTime > 0){
            this._stopTime = this._stopTime - dt
            if(this._stopTime <= 0 ){ //空转时间到了
                if(this.CanStopSlot()){//满足开始停止的条件
                    cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_2")
                    //倒计时完，设置一次
                    for(let i = 0; i < this._reels.length; i++ ){
                        let item = this._reels[i]
                        let col = i % this._col
                        let reelStopInterv = cc.vv.gameData.GetSlotsScript().GetReelStopInter(col)
                        item.StopMove(reelStopInterv)
                    }
                }
                else{
                    //如果没有结果,则延迟一帧
                    this._stopTime = dt

                    //记录一个超时时间.
                    this._roundSpineTime = this._roundSpineTime || 0
                    this._roundSpineTime += dt
                    if(this._roundSpineTime > 30 ){
                        // this._stopTime = -1
                        cc.vv.gameData.GetTopScript().SetBackLobby(true)
                    }
                }

            }
        }
    },

    StopMove:function(){
        this._bStopRightnow = true
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1")
        this.unschedule(this.StartMove)

        this._stopTime = -1
        for(let i = 0; i < this._reels.length; i++ ){
            let item = this._reels[i]
            let reelStopInterv = 0 //立即停止
            item.StopMove(reelStopInterv)
            item.StopMoveRightNow()
        }
    },

    updateData(coin){
        this._coin += coin
        let winCoinAni = this._winCoinRoot.getComponent(cc.Animation)
        winCoinAni.play("shoujifankuiguang")
        let lizi = cc.find("lizi",this._winCoinRoot)
        lizi.active = true
        lizi.getComponent(cc.ParticleSystem).resetSystem()
        lizi.stopAllActions()
        cc.vv.gameData.GetBottomScript().SetWin(coin + cc.vv.gameData.GetBottomScript().getCurrentWin())
        cc.find("coin",this._winCoinRoot).getComponent(cc.Label).string = Global.FormatNumToComma(this._coin)
        cc.tween(lizi).delay(1).call(()=>{
            lizi.active = false
        }).start()
    },

    ShowResult(bonusIdxs,bonusItems){
        return new Promise(async (success,failed)=>{
            let result = []
            for (let i = 0; i < bonusIdxs.length; i++) {
                const idx = bonusIdxs[i]
                let row = this._row - Math.floor((idx -1)/this._col) -1
                if(row < this._unlockRow){
                    result.push({idx:bonusIdxs[i],data:bonusItems[i]})
                }
            }
            let sortArray = (a,b)=>{
                let acol = (a.idx - 1) % this._col
                let bcol = (b.idx - 1) % this._col
                if(acol == bcol){
                    return a.idx - b.idx
                }else{
                    return acol - bcol
                }
            }
            result.sort(sortArray)
            this._winCoinRoot.active = true
            this._coin = 0
            cc.find("coin",this._winCoinRoot).getComponent(cc.Label).string = ""
            await this.awaitTime(1)
            for (let i = 0; i < result.length; i++) {
                const ret = result[i]
                //珍珠做表现
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.Mermaid_scatter_down)
                let reel = this._reels[ret.idx - 1]
                if(reel){
                    reel._symbols[0].playSettleAnimation();
                }
                await this.awaitTime(0.8)
                if(ret.data.jackpot){
                    await cc.vv.gameData.getPopWinManage().showJackpotWinCoin(ret.data.jackpot.value,ret.data.jackpot.id)
                    this.updateData(ret.data.jackpot.value)
                }else{
                    this.updateData(ret.data.coin)
                }
                await this.awaitTime(0.2)
            }
            await cc.vv.gameData.getPopWinManage().showPearlsLinkWinCoin(this._gameInfo.bonusGame.winCoin)
            cc.vv.gameData.AddCoin(this._gameInfo.bonusGame.winCoin)
            success()
        })
    },
});
