/**
 * 美人鱼与珍珠
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
       _canShowStop:false,
        _qipaoList:[],
        _scatterNum:0,
    },

    onLoad(){
        this._super()
        for (let i = 1; i < 21; i++) {
            let qipao = cc.find("qipaoRoot/qipao"+i,this.node)
            this._qipaoList.push(qipao)
        }
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    //重写
    StartMove:function(){
        Global.SlotsSoundMgr.playNormalBgm()

        this._bStopRightnow = null
        this._gameInfo = null

        //top状态更新
        this._topScript.StartMove()

        //清理数据
        cc.vv.gameData.ClearOneRoundData()

        //每列转起来
        this.MoveReels(this._reels)

        

        //设置停止时间
        //就是收到结果后，如果多少秒会开始停止
        this._stopTime = this.GetStopTime()

        this._canShowStop = false
        this._roundSpineTime = 0
        this._scatterNum = 0
    },

    //重写
    //gameData模块收到数据后，转发到此处
    async onMsgSpine(msg){
        this._gameInfo = msg
        let cards = msg.resultCards
        this.SetSlotsResult(cards,msg.bonusIdxs,msg.bonusItems)
        this.SetReelStateInfo(cards)
        this._canShowStop = true
    },

    SetSlotsResult:function(cards,bonusIdxs,bonusItems){
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if(this._cfg.symbol[cards[i]]){
                let res = {}
                res.sid = cards[i] //符号id
                for (let j = 0; j < bonusIdxs.length; j++) {
                    if((i+1) === bonusIdxs[j]){
                        res.data = bonusItems[j]
                        break
                    }
                }
                if(!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }

        }

        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    ShowWinTrace:function(){
        let allWinIdx = []

        //中奖位置
        for(let i = 0; i < this._gameInfo.zjLuXian.length; i++){
            let item = this._gameInfo.zjLuXian[i]
            for(let idx = 0; idx < item.indexs.length; idx++){
                allWinIdx[item.indexs[idx]] = 1
            }
        }

        let skipBorderAniIdxs = [];
        if(this._gameInfo.scatterZJLuXian && this._gameInfo.scatterZJLuXian.indexs){
            for(let i = 0; i < this._gameInfo.scatterZJLuXian.indexs.length; i++){
                let val = this._gameInfo.scatterZJLuXian.indexs[i]
                allWinIdx[val] = 1
            }
            let idxs = this._gameInfo.scatterZJLuXian.indexs
            idxs = Array.isArray(idxs) ? idxs : (idxs && typeof(idxs) === "object") ? Object.values(idxs) : []
            skipBorderAniIdxs = /*this._gameInfo.scatterZJLuXian.indexs*/idxs.concat(); // By JerryWong
        }

        //总
        for (const key in allWinIdx) {
            let symbol = this.GetSymbolByIdx(Number(key))
            if(symbol){
                symbol.playWinAnimation()
                if(!skipBorderAniIdxs.includes(Number(key))) {
                    symbol.ShowKuang()
                }
            }
            this.hideQiPaoByIdx(Number(key))
        }


    },

    ShowWinCoin(nAddWin,nTotalWin,bUpdateBalance){
        return new Promise(async (sucess, failed)=>{
            this.ShowBottomWin(nAddWin,nTotalWin,bUpdateBalance,sucess)
        });
    },

    //全部列都停止了,重写
    //处理停下后的中奖情况，这里多数情况需要根据自己的逻辑来处理
    async OnSpinEnd(){
        console.log(">>>> BunnyGirl_Slots OnSpinEnd已废弃不用")
    },

    //重写
    //备份当前状态
    Backup() {
        this._super()
    },

    //重写
    //恢复到保存的状态
    Resume() {
        for (let i = 0; i < this._reels.length; i++) {
            const reel = this._reels[i];
            for (let j = 0; j < reel._symbols.length; j++) {
                const symbol = reel._symbols[j];
                symbol.setAnimationToTop(false)
            }
        }
        this._super()
    },

    CanStopSlot(){
        return this._canShowStop
    },

    async hideQiPaoByIdx(idx){
        let collectNode = cc.find("collectNode",this.node.parent)
        let qipao = this._qipaoList[idx-1]
        if(qipao && qipao.active){
            let qipaoAni = qipao.getComponent(cc.Animation)
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.Mermaid_IceQiPap_Fly)
            qipaoAni.play("qipaoDisappear")
            qipaoAni.on("finished",()=>{
                qipaoAni.off("finished")
                qipao.active = false
            })
            await this.awaitTime(0.5)
            let qppos = qipao.convertToWorldSpaceAR(cc.v2(0,0))
            let startPos = collectNode.convertToNodeSpaceAR(qppos)
            let flyNode = cc.instantiate(cc.vv.gameData.GetPrefabByName("flyPoint"))
            flyNode.parent = collectNode
            flyNode.position = startPos
            let destNode = cc.vv.gameData.getCollectNode().getOnePoint()
            if(destNode){
                let destPos = destNode.convertToWorldSpaceAR(cc.v2(0,0))
                let endPos = collectNode.convertToNodeSpaceAR(destPos)
                cc.tween(flyNode).to(0.5,{position:endPos},{easing:"quadIn"}).call( ()=>{
                    cc.vv.gameData.getCollectNode().addOnePoint()
                    flyNode.parent = null
                }).start()
            }
        }
    },

    restQiPao(){
        for (let i = 0; i < this._qipaoList.length; i++) {
            const qipao = this._qipaoList[i]
            qipao.active = true
            let qipaoAni = qipao.getComponent(cc.Animation)
            qipaoAni.play("qipaoNormal")
        }
    },

    recoveryQiPao(qipaolist){
        for (let i = 0; i < this._qipaoList.length; i++) {
            const qipao = this._qipaoList[i]
            qipao.active = false
        }
        for (let i = 0; i < qipaolist.length; i++) {
            let idx = qipaolist[i]
            const qipao = this._qipaoList[idx - 1]
            if(qipao){
                qipao.active = true
                let qipaoAni = qipao.getComponent(cc.Animation)
                qipaoAni.play("qipaoNormal")
            }
        }
    },
});
