    clearSlots(){
        for (let i = 0; i < this._slots1reel.length; i++) {
            const reel = this._slots1reel[i]
            for (let j = 0; j < reel._symbols.length; j++) {
                const symbol = reel._symbols[j]
                symbol.ShowNormal()
            }
        }
        for (let i = 0; i < this._slots2reel.length; i++) {
            const reel = this._slots2reel[i]
            for (let j = 0; j < reel._symbols.length; j++) {
                const symbol = reel._symbols[j]
                symbol.ShowNormal()
            }
        }
        this.hideSlotsKuang()
    },

    StopMove:function(){
        this._bStopRightnow = true
        this._bottomScript.ShowBtnsByState("moveing_1")

        this._stopTime = -1
        for(let i = 0; i < this._slots1reel.length; i++ ){
            let item = this._slots1reel[i]
            let reelStopInterv = 0 //立即停止
            item.StopMove(reelStopInterv)
            item.StopMoveRightNow()
        }
        for(let i = 0; i < this._slots2reel.length; i++ ){
            let item = this._slots2reel[i]
            let reelStopInterv = 0 //立即停止
            item.StopMove(reelStopInterv)
            item.StopMoveRightNow()
        }
    },
