
/**埃及幻想-符号表
 * 
*/
cc.Class({
    extends: require("BunnyGirl_symbol"),

    properties: {
        
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init:function(idx,node){
        this._topAniNode = node
        this.SetSymbolIdx(idx);

        this.InitSymbol()
    },

    InitSymbol(){
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(2,cfg.randomSymbolsBonus.length)
        let randVal = cfg.randomSymbolsBonus[randIdx-1];
        this.ShowById(randVal)
        this.setTopNodeGray(false);
        this.setAnimationToTop(false);
    },

    //显示随机符号,这个bonusGame Reel数量太多，之间并没有区别，所以还是用老的配置
    GetRandomCfg:function(){
        return null
    },

    ShowById(id,data){
        this._super(id,data)
        if(id === 3){
            cc.find("mask",this.node).active = false
        }else{
            cc.find("mask",this.node).active = true
        }
    },

    //设置框体的父节点
    //根据层级可能需要重写
    GetKuangShowParent:function(){
        return this._topAniNode
    },

    // 结算动画
    playSettleAnimation(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()

        if(cfg.symbol[id] && cfg.symbol[id].settle_ani) {
            this._state = "stop";
            if (this._showNode) {
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].node, aniNode)
            topShowNode.active = true
            if (cfg.symbol[id].settle_ani.name !== "") {
                aniNode.zIndex = cfg.symbol[id].settle_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
                let nodeAnimation = topShowNode.getComponent(cc.Animation)
                if (nodeAnimation) {
                    nodeAnimation.play(cfg.symbol[id].settle_ani.name)
                    nodeAnimation.on("finished", () => {
                        nodeAnimation.off("finished");
                        this.setSymbolGray(true, topShowNode);
                    })
                }
            }
        }
    },

    // 主要用来设置top层bonus节点灰太恢复正常状态
    setTopNodeGray(bGray){
        let cfg = cc.vv.gameData.getGameCfg()
        let topNode = cc.find(cc.js.formatStr("symbol_ani_%s_%s",this._symbolIdx,this._reelIdx),this._topAniNode);
        if(topNode){
            let bonusNode = cc.find(cfg.symbol[3].node, topNode);
            if(bonusNode){
                this.setSymbolGray(bGray, bonusNode);
            }
        }
    },

    setSymbolGray(bGray, node){
        let nState = '2d-sprite';
        if (bGray) {
            nState = '2d-gray-sprite'
        }

        node.getComponent(cc.Sprite).setMaterial(0, cc.Material.getBuiltinMaterial(nState))
        if(node.childrenCount > 0){
            node.children.forEach(child=>{
                if(child.getComponent(cc.Sprite)){
                    child.getComponent(cc.Sprite).setMaterial(0, cc.Material.getBuiltinMaterial(nState))
                } else if(child.getComponent(cc.Label)){
                    child.getComponent(cc.Label).setMaterial(0, cc.Material.getBuiltinMaterial(nState))
                }
            })
        }
    },

    // update (dt) {},
});
