cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {

    },

    InitCommComponent:function(){
        this._super()

        let safeNode = cc.find('Canvas/safe_node')
        let popWinManage = safeNode.getComponentInChildren("BunnyGirl_Pop")
        if(popWinManage){
            cc.vv.gameData.setPopWinManage(popWinManage)
        }
        let qieping = safeNode.getComponentInChildren("BunnyGirl_qiePing")
        if(qieping){
            cc.vv.gameData.setQiePing(qieping)
        }
        let collect = safeNode.getComponentInChildren("BunnyGirl_collectNode")
        if(collect){
            cc.vv.gameData.setCollectNode(collect)
        }
        let node_slots = cc.find('slots',safeNode)
        let script_slots = node_slots.getComponent("BunnyGirl_Slots")
        cc.vv.gameData.addSlotsScript(script_slots)
        let node_slotsfree = cc.find('slotsfree',safeNode)
        let script_slotsfree = node_slotsfree.addComponent("BunnyGirl_Slotsfree")
        cc.vv.gameData.addSlotsScript(script_slotsfree)
        let manage = safeNode.getComponent("BunnyGirl_manage")
        if(manage){
            cc.vv.gameData.setManage(manage)
        }
        let pickGame = safeNode.getComponentInChildren("BunnyGirl_pick")
        if(pickGame){
            cc.vv.gameData.setPickGame(pickGame)
        }
        let bonusGame = safeNode.getComponentInChildren("BunnyGirl_bonusGame")
        if(bonusGame){
            cc.vv.gameData.setBonusGame(bonusGame)
        }

        let prizePool = safeNode.getComponentInChildren("BunnyGirl_PrizePool")
        if(prizePool) {
            cc.vv.gameData.setPrizePool(prizePool);
        }
    },

    // update (dt) {},
});
