/**
 * 游戏自己的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        _popWinManage:null,
        _qiePing:null,
        _collectNode:null,
        _slotsArray:[],
        _slotsIndex:0,
        _manage:null,
        _pickGame:null,
        _bonusGame:null,
        _prizePool:null,
    },

    reconnect(){
        return new Promise(async (success,failed)=>{
            this._collectNode.init(this._deskInfo.bubbleBonus.count)
            this._slotsArray[0].recoveryQiPao(this._deskInfo.bubbleBonus.unCollectIdxs)
            if(this._deskInfo.bonusGame){
                await this._bonusGame.showBonusGame(this._deskInfo.bonusGame,true)
                if(this._deskInfo.bubbleGame){
                    await cc.vv.gameData.getManage().enterPickGame()
                }
            }else{
                if(this._deskInfo.bubbleGame){
                    await this._pickGame.recoveryPickGame(this._deskInfo.bubbleGame)
                }
            }
            success()
        })
    },

    setPopWinManage(script){
        this._popWinManage = script
    },

    getPopWinManage(){
       return this._popWinManage
    },

    setQiePing(script){
        this._qiePing = script
    },

    getQiePing(){
        return this._qiePing
    },

    setCollectNode(script){
        this._collectNode = script
    },

    getCollectNode(){
        return this._collectNode
    },

    addSlotsScript(script){
        this._slotsArray.push(script)
    },

    //获得游戏的slots脚本
    GetSlotsScript:function(){
        if(this._slotsIndex > 1 || this._slotsIndex < 0){
            this._slotsIndex = 0
        }
        return this._slotsArray[this._slotsIndex]
    },

    //将脚本转成免费游戏
    changeSlotsFree(){
        this._slotsIndex = 1
    },

    //将脚本转成普通游戏
    changeSlotsNormal(){
        this._slotsIndex = 0
    },

    setManage(script){
        this._manage = script
    },

    getManage(){
        return this._manage
    },

    setPickGame(script){
        this._pickGame = script
    },

    getPickGame(){
        return this._pickGame
    },

    setBonusGame(script){
        this._bonusGame = script
    },

    getBonusGame(){
        return this._bonusGame
    },

    setPrizePool(script){
        this._prizePool = script
    },

    getPrizePool(){
        return this._prizePool
    },

    // update (dt) {},
});
