/**埃及幻想-符号表 
 * 
*/
cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {
        _randSymbolNum:0,
        _randSymbolVal:0,
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    //为了让跨4行的美人鱼卷轴出现的不是特别突兀，现将卷轴额外的行扩充4行，相应的结果要多设置3个随机的值
    LoadSymbols:function(){
        let url = this._cfg.symbolPrefab

        if(!this._symbolTemplete){
            this._symbolTemplete = cc.vv.gameData.GetPrefabByName(url)
            if(this._symbolTemplete){
                this._symbolTemplete.optimizationPolicy = cc.Prefab.OptimizationPolicy.MULTI_INSTANCE
            }
        }
        for(let i = 0; i < this._nCount+4; i++){
            this.CreateOneSymbol()
        }
        this.ReLayOut()

    },

    //列停止
    OnReelSpinEnd:function(){
        this._reelState = []
        let slots = cc.vv.gameData.GetSlotsScript()
        slots.OnReelSpinEnd(this._reelIdx)

        //不能判断，停下来的列等于总共的列，因为有时候只旋转了3列
        //停下来的列以及等于最后一列旋转的列，
        //说明整个列已经停止
        let lastReelStopIdx = slots.GetLastStopReelIdx()
        if(this._reelIdx == lastReelStopIdx){
            //所有列都停止了
            cc.vv.gameData.getManage().OnSpinEnd()
        }
    },

    //创建一个符号元素
    CreateOneSymbol:function(){
        let node = cc.instantiate(this._symbolTemplete)
        node.parent = this._holderNode
        let scp = node.addComponent(this._cfg.scripts.Symbols)
        let idx = this._symbols.length; //行号
        scp.SetSymbolReelIdx(this._reelIdx)
        scp.Init(idx,this._topAniNode)
        if(this._randSymbolNum > 0){
            this._randSymbolNum--
            scp.ShowById(this._cfg.symbolArray[this._randSymbolVal][this._randSymbolNum])
        }else{
            this._randSymbolVal = scp.ShowRandomSymbol()
            if(this._randSymbolVal == 104){
                this._randSymbolNum = this._cfg.symbolArray[this._randSymbolVal].length
                this._randSymbolNum--
            }else{
                this._randSymbolNum = 0
            }
        }
        this._symbols.push(scp)


    },

    //显示免费游戏加速效果
    //加速框的显示
    ShowAntiEffect:function(bShow,name){
        this._super(bShow,name)
        let diNode = cc.find("mask/jiliBg",this.node)
        if(diNode){
            diNode.active = bShow
        }
    },

    updataSymbol(){
        let symbol = this._symbols.shift()
        let symbolData = null
        if(this._stopTime <= 0 && this._bStoping && this._result && !this._bResizing) {
            if(this._result instanceof Array){
                //开始设置结果
                this.ReadyToStop()
                this._randSymbolNum = 0
                this._randSymbolVal = 0
                symbolData = this._result.shift()
                if(!symbolData){
                    this._bMoving = false
                }
            }
            else{
                console.log('>>>> LMSlots_Reel_Base.updataSymbol设置的结果不是数组!')
            }
        }
        if (symbolData) {
            symbol.ShowById(symbolData.sid,symbolData.data)
        }else{
            if(this._randSymbolNum > 0){
                this._randSymbolNum--
                symbol.ShowById(this._cfg.symbolArray[this._randSymbolVal][this._randSymbolNum])
            }else{
                this._randSymbolVal = symbol.ShowRandomSymbol()
                this._randSymbolNum = this._cfg.symbolArray[this._randSymbolVal].length
                this._randSymbolNum--
            }
        }

        this._symbols.push(symbol)
        this.ReLayOut()
        this._curY = 0
        this._holderNode.y = this._holderOrigPosY
        if(!this._bMoving){
            this.OnReelBounsAction()
        }
    },

    //已经准备开始停止了
    //即：开始设置结果，已经进入了停止周期，stoptime变负的那一刻
    //执行在回弹之前
    ReadyToStop:function(){
        if(!this._bNotifyReadyStop){
            this._bNotifyReadyStop = true
            let slots = cc.vv.gameData.GetSlotsScript()
            slots.OnReelReadyToStop(this._reelIdx)
            //倒数第3个symbol是马上将要显示到卷轴中的，如果这个symbol是104，代表美人鱼必然显示不完整
            //将最后3个symbol值做一个强制修改，将101~104的图标，随机成其他图标，保证跨4行的美人鱼图标连贯，不会突兀消失，造成画面会闪一下
            let startIdx = this._symbols.length - 3
            if(this._symbols[startIdx]._id === 104){
                for (let i = startIdx; i < this._symbols.length; i++) {
                    const symbol = this._symbols[i]
                    symbol.changeOther()
                }
            }else if(this._symbols[startIdx + 1]._id === 104){
                for (let i = startIdx + 1; i < this._symbols.length; i++) {
                    const symbol = this._symbols[i]
                    symbol.changeOther()
                }
            }else if(this._symbols[startIdx + 2]._id === 104){
                for (let i = startIdx + 2; i < this._symbols.length; i++) {
                    const symbol = this._symbols[i]
                    symbol.changeOther()
                }
            }
        }
    },

    playReelStop(){
        //判断 是否播放停止动画
        //TODO 停止动画，其实不应该和加速的配置有关系。再次最好写成一个接口
        if (this._originResult) {
            for(let i = 0; i < this._originResult.length - 3; i++){ //有4行是无效数据，为了效果而加
                let item = this._symbols[i]
                for (let info of this._reelState) {
                    if (info.isStop && info.id.includes(item.GetShowId())) {
                        item.playStopAnimation(true)
                    }
                }
            }
        }

        //判断播放音效
        if (this._cfg.reelStateInfo && this._cfg.reelStateInfo[0]) {
            let reelStopEffect = ''
            let symbolEffect = ''
            let hasSymbol = false
            for (let info of this._reelState) {
                if (info.isStop) {
                    symbolEffect = info.symbolStopSound ? info.symbolStopSound : ''
                    hasSymbol = true
                }else{
                    reelStopEffect = info.reelStopSound ? info.reelStopSound : ''
                }
            }
            if (hasSymbol) {
                reelStopEffect = symbolEffect
            }
            if(reelStopEffect === "Mermaid_scatter_down"){
                if(cc.vv.gameData.GetSlotsScript()._scatterNum === 0){
                    reelStopEffect = "Mermaid_scatter_down"
                    cc.vv.gameData.GetSlotsScript()._scatterNum++
                }else if(cc.vv.gameData.GetSlotsScript()._scatterNum === 1){
                    reelStopEffect = "Mermaid_scatter_down2"
                    cc.vv.gameData.GetSlotsScript()._scatterNum++
                }else if(cc.vv.gameData.GetSlotsScript()._scatterNum === 2){
                    reelStopEffect = "Mermaid_scatter_down3"
                    cc.vv.gameData.GetSlotsScript()._scatterNum++
                }
            }

            //有配置的话用配置的音效路径，没有的话，用默认的
            let soundPath = this._cfg.reelStateInfo[0].path
            if(!soundPath){
                soundPath = cc.vv.gameData.getGameDir()
            }
            cc.vv.AudioManager.playEff(soundPath, reelStopEffect, true);
        }
    },

    //卷轴额外加了4行，结果多随机3个
    SetResult:function(val){
        this._originResult = Global.copy(val)
        this._result = val
        let num = 3
        let lastSymbol = this._originResult[this._originResult.length - 1].sid
        if(lastSymbol > 101){  //如果结果最后是跨行的symbol，把结果补全
            for (let i = 0; i < lastSymbol - 101; i++) {
                this._originResult.push({sid:(lastSymbol - i - 1)})
                this._result.push({sid:(lastSymbol - i - 1)})
                num--
            }
        }
        if(num > 0){
            for (let i = 0; i < num; i++) {
                let randIdx = Global.random(1,this._cfg.randomSymbols.length)
                let randVal = this._cfg.randomSymbols[randIdx-1]
                if(randVal === 3){
                    this._originResult.push({sid:randVal,data:{coin:cc.vv.gameData.GetTotalBet()}})
                    this._result.push({sid:randVal,data:{coin:cc.vv.gameData.GetTotalBet()}})
                }else{
                    this._originResult.push({sid:randVal})
                    this._result.push({sid:randVal})
                }
            }
        }
    },
    // update (dt) {},
});
