cc.Class({
    extends: cc.Component,

    properties: {
        _pointList:[],
        _pointIdx:0,
        _hailuo:null,
        _tips:null,
        _tempPointIdx:0,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        for (let i = 1; i < 21; i++) {
            let point = cc.find("point"+i,this.node)
            this._pointList.push(point)
        }
        this._hailuo = cc.find("hailuo",this.node)
        this._hailuo.on("click",this.onClickHaiLuo,this)
        this._tips = cc.find("tips",this.node)
        this._tips.active = false
    },

    start () {
        
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    onClickHaiLuo(){
        this._hailuo.getComponent(cc.Button).interactable = false
        this._tips.active = true
        this._tips.scale = 0
        cc.tween(this._tips).to(0.5,{scale:1},{easing:"backOut"}).delay(2).to(0.5,{scale:0},{easing:"backIn"}).call(()=>{
            this._hailuo.getComponent(cc.Button).interactable = true
            this._tips.active = false
        }).start()
    },

    // update (dt) {},

    init(num){
        if(num > 20){
            num = 20
        }
        for (let i = 0; i < num; i++) {
            const point = this._pointList[i]
            cc.find("select",point).active = true
        }
        this._pointIdx = num
        this._tempPointIdx = num
    },

    async addOnePoint(){
        this._pointIdx++
        if(this._pointIdx > 20){
            this._pointIdx = 20
            return
        }
        let point = this._pointList[this._pointIdx-1]
        let effect = cc.find("jindutiaoqipaolizi",point)
        let effectAni = effect.getComponent(cc.Animation)
        effect.active = true
        effectAni.play("jindutiaoqipaolizi")
        effectAni.on("finished",()=>{
            effectAni.off("finished")
            effect.active = false
        })
        cc.find("select",point).active = true
    },

    showJiMan(){
        let hailuoAni = this._hailuo.getComponent(cc.Animation)
        hailuoAni.play("hailuoJiManEffect")
    },

    getOnePoint(){
        this._tempPointIdx++
        if(this._tempPointIdx > 20){
            this._tempPointIdx = 20
        }
        return this._pointList[this._tempPointIdx-1]
    },

    recovery(){
        this._pointIdx = 0
        this._tempPointIdx = 0
        for (let i = 0; i < this._pointList.length; i++) {
            const point = this._pointList[i]
            cc.find("select",point).active = false
            cc.find("jindutiaoqipaolizi",point).active = false
        }
    }
});
