cc.Class({
    extends: cc.Component,

    properties: {
        _isInFree:false,
        _isInBonus:false,
    },

    onLoad(){
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA,this.onRecvClickQiQiu,this);
    },

    onDestroy(){
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA,this.onRecvClickQiQiu,false,this);
    },

    start(){
        this.ReconnectShow()
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    /**
     * 收到51号协议
     * @param {*} msg
     */
    async onRecvClickQiQiu(msg){
        if(msg.code == 200){
            if(msg.data.rtype === 1){
                cc.vv.gameData.getBonusGame().OnMsgSpin(msg.data)
            }else if(msg.data.rtype === 2){
                cc.vv.gameData.getPopWinManage().onSelectBonus(msg.data.choiceId,msg.data.bubbleGame.restCnt,msg.data.bubbleGame)
            }
        }
    },

    async OnSpinEnd(){
        let _gameInfo = cc.vv.gameData.GetSlotsScript()._gameInfo
        if(!_gameInfo){
            return
        }
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1")

        if(_gameInfo.bonusWinCoin && _gameInfo.bonusWinCoin > 0){
            let curWin = cc.vv.gameData.GetBottomScript().getCurrentWin()
            cc.vv.gameData.GetBottomScript().SetWin(curWin + _gameInfo.bonusWinCoin)
            for (let i = 0; i < _gameInfo.bonusIdxs.length; i++) {
                const idx = _gameInfo.bonusIdxs[i]
                let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(idx)
                if(symbol){
                    symbol.playStopAnimation()
                }
            }
            await this.awaitTime(1)
        }

        //显示中奖路线
        cc.vv.gameData.GetSlotsScript().ShowWinTrace()
        //显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        let isNormalGame = true
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
            isNormalGame = false
        }

        await cc.vv.gameData.GetSlotsScript().ShowWinCoin(nWin,nTotal,isNormalGame)

        if(_gameInfo.bonusGame){  //触发bonusGame
            for (let i = 0; i < _gameInfo.bonusGame.bonusIdxs.length; i++) {
                let idx = _gameInfo.bonusGame.bonusIdxs[i]
                if(idx > 20){
                    idx -= 20
                }
                let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(idx)
                if(symbol){
                    symbol.playWinAnimation()
                }
                cc.vv.gameData.GetSlotsScript().hideQiPaoByIdx(idx)
            }
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.Mermaid_TriggerRespin)
            await this.awaitTime(2)
            await this.enterBonusGame(_gameInfo.bonusGame)
        }

        if(_gameInfo.bubbleGame){  //收集泡泡游戏
            await this.enterPickGame()
        }

        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){  //免费次数中
            if(_gameInfo.freeResult){
                if(_gameInfo.freeResult.freeInfo && _gameInfo.freeResult.freeInfo.scatterIdx){//免费中免费
                    for (let i = 0; i < _gameInfo.freeResult.freeInfo.scatterIdx.length; i++) {
                        const key = _gameInfo.freeResult.freeInfo.scatterIdx[i];
                        let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(Number(key))
                        if(symbol){
                            symbol.playWinAnimation()
                        }
                    }
                    if(_gameInfo.freeResult.freeInfo.freeCnt > 0){
                        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bell)
                        await this.awaitTime(2)
                        await this.CheckFreeEnterFreeGame(_gameInfo.freeResult.freeInfo.freeCnt);
                    }
                }
            }
        }else{
            if(_gameInfo.freeResult){
                if(_gameInfo.freeResult.freeInfo && _gameInfo.freeResult.freeInfo.scatterIdx){//免费中免费
                    for (let i = 0; i < _gameInfo.freeResult.freeInfo.scatterIdx.length; i++) {
                        const key = _gameInfo.freeResult.freeInfo.scatterIdx[i];
                        let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(Number(key))
                        if(symbol){
                            symbol.playWinAnimation()
                        }
                    }
                    if(_gameInfo.freeResult.freeInfo.freeCnt > 0){
                        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.Mermaid_scatter_TriggerFreespin)

                        await this.awaitTime(2)
                        await this.CheckEnterFreeGame(_gameInfo.freeResult.freeInfo.freeCnt);
                    }
                }
            }
        }

        //触发退出免费
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() == 0){
            await this.CheckExitFreeGame();
        }
        cc.vv.gameData.GetSlotsScript().CanDoNextRound()
    },

    //检查退出免费
    async CheckExitFreeGame(){
        return new Promise(async (sucess, failed)=>{
            let nWin = cc.vv.gameData.GetGameTotalFreeWin()
            let nTotal = nWin
            await cc.vv.gameData.getPopWinManage().showFreeGameWinCoin(nWin,cc.vv.gameData.GetTotalFree())
            await this.changeSlotsNormal()
            cc.vv.gameData.SetTotalFree(0)
            await cc.vv.gameData.GetSlotsScript().ShowWinCoin(nWin,nTotal,true)
            Global.SlotsSoundMgr.playNormalBgm(true)
            sucess()
        });
    },

    //免费进入免费
    async CheckFreeEnterFreeGame(freecnt){
        return new Promise(async (sucess,failed)=>{
            await cc.vv.gameData.getPopWinManage().showFreeGametri(freecnt, true)
            // await this.awaitTime(1)
            sucess()
        })
    },

    //检查进入免费
    async CheckEnterFreeGame(freecnt){
        return new Promise(async (sucess, failed)=>{
            await cc.vv.gameData.getPopWinManage().showFreeGametri(freecnt, false);
            await this.changeSlotsFree()
            Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.music_Mermaid_FreespinBG)
            sucess();
        });
    },

    //断线重连的显示,重写
    //可根据自己断线逻辑重写
    async ReconnectShow(){
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1")
        let rest = cc.vv.gameData.GetFreeTime()
        if(rest){
            this.ShowGameview(true)
            this.ShowFreeTimes(true)
            Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.music_Mermaid_FreespinBG)
            cc.vv.gameData.changeSlotsFree()
            cc.vv.gameData.GetSlotsScript().recoveryFree()
        }
        else{
            // Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Mermaid_enter)
            this.ShowGameview(false)
            this.ShowFreeTimes(false)
            cc.vv.gameData.changeSlotsNormal()
        }
        await cc.vv.gameData.reconnect()
        cc.vv.gameData.GetSlotsScript().CanDoNextRound()
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview:function(bFree){
        this._isInFree = bFree
        if(bFree){
            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()

            //显示免费次数
            // this._bottomScript.ShowFreeModel(true,total-rest,total)
            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            cc.vv.gameData.GetBottomScript().SetWin(nTotal)
            cc.vv.gameData.getPrizePool().alignTop();
        }
        else{
            // this._bottomScript.ShowFreeModel(false)
            cc.vv.gameData.getPrizePool().toNormal();
        }

        //可能还需要显示免费背景图
        let normalBg = cc.find("Canvas/safe_node/spr_bg_normal")
        let normalFree = cc.find("Canvas/safe_node/spr_bg_free")
        if(normalFree){ //存在免费游戏背景才执行下面的逻辑
            if(normalBg){
                normalBg.active = !bFree
            }
            normalFree.active = bFree
        }

        // cc.vv.gameData.showOtherSysNode(!bFree);
    },

    ShowFreeTimes(bFree){
        if(bFree){
            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()
            //显示免费次数
            cc.vv.gameData.GetBottomScript().ShowFreeModel(true,total-rest,total)
        }
        else{
            cc.vv.gameData.GetBottomScript().ShowFreeModel(false)
        }
    },

    changeSlotsFree(){
        return new Promise(async (success,failed)=>{
            cc.vv.gameData.changeSlotsFree()
            await cc.vv.gameData.GetSlotsScript().showFreeGame(()=>{
                this.ShowGameview(true)
            })
            this.ShowFreeTimes(true)
            success()
        })
    },

    changeSlotsNormal(){
        return new Promise(async (success,failed)=>{
            await cc.vv.gameData.getQiePing().showQiePing1(()=>{
                this.ShowGameview(false)
                cc.vv.gameData.GetSlotsScript().node.active = false
                cc.vv.gameData.changeSlotsNormal()
            })
            this.ShowFreeTimes(false)
            success()
        })
    },

    enterPickGame(){
        return new Promise(async (success,failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Mermaid_TriggerBonus)
            cc.vv.gameData.getCollectNode().showJiMan()
            await this.awaitTime(2)
            cc.vv.gameData.getQiePing().showQiePing1()
            await this.awaitTime(0.5)
            await cc.vv.gameData.getPickGame().showPickGame()
            success()
        })
    },

    enterBonusGame(data){
        return new Promise(async (success,failed)=>{
            await cc.vv.gameData.getPopWinManage().showPearlsLinkTri()

            cc.vv.gameData.getQiePing().showQiePing1()
            await this.awaitTime(3)
            await cc.vv.gameData.getBonusGame().showBonusGame(data)
            success()
        })
    },

    // update (dt) {},
});