cc.Class({
    extends: cc.Component,

    properties: {
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
    },

    start() {

    },

    awaitTime(time){
        return new Promise((success, failed)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },

    //冒泡泡加美人鱼飞吻
    async showQiePing1(callBack){
        let character = cc.find("Canvas/safe_node/Mermaid_idle");
        character.active = false;

        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Mermaid_GuoChang)
        let spine = this.node.getChildByName("spine").getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, "skill", false);
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            spine.node.active = false;
        })
        await this.awaitTime(2.7);
        character.active = true;
        if(callBack){
            callBack()
        }
    },


    //单纯冒泡泡，没有美人鱼
    showQiePing2(callBack){
        this.showQiePing1(callBack);
    },
})