    showWin(){
        let popBg = cc.find("popup",this.node)
        popBg.active = true
        popBg.opacity = 0
        cc.tween(popBg).to(0.3,{opacity:255}).start()
    },

    hideWin(callBack){
        let popBg = cc.find("popup",this.node)
        cc.tween(popBg).to(0.3,{opacity:0}).call(()=>{
            if(callBack){
                callBack()
            }
            popBg.active = false
        }).start()
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    showFreeGametri(freecnt, bExtra = false){
        return new Promise(async (success,failed)=>{
            if(!bExtra){
                Global.SlotsSoundMgr.stopBgm();
            }
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Mermaid_Freespin_OverView)
            this.showWin()
            let showNode = cc.find("show_freeGame_tri",this.node)
            showNode.active = true
            cc.find("bg/freeGameBg/free_more",showNode).active = bExtra;
            cc.find("bg/freeGameBg/free_nor",showNode).active = !bExtra;
            // let particle = cc.find("numBg/lizi",showNode)
            // particle.active = false
            let coin = cc.find("numBg/num",showNode)
            coin.getComponent(cc.Label).string = freecnt
            let showNodeAnimation = showNode.getComponent(cc.Animation)
            showNodeAnimation.play("showFreeGameWinCoin")
            // particle.active = true
            // particle.getComponent(cc.ParticleSystem).resetSystem()
            let collectButton = cc.find("bg/collectBtn",showNode)
            if(bExtra){
                collectButton.opacity = 0
            } else {
                collectButton.opacity = 255
            }
            // this.scheduleOnce(()=>{
            //     particle.active = false
            // },1.5)
            showNodeAnimation.on("finished",()=>{
                showNodeAnimation.off("finished")
                showNodeAnimation.play("popWinIdel")


                let self = this;
                let clickFunc = async ()=>{
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.click)
                    if(!bExtra){
                        collectButton.getComponent(cc.Button).interactable = false
                    }
                    showNodeAnimation.play("hideFreeGameWinCoin")
                    showNodeAnimation.on("finished",()=>{
                        showNodeAnimation.off("finished")
                        showNode.active = false
                        self.hideWin(()=>{
                            success()
                        })
                    })
                };

                if(bExtra){
                    collectButton.off("click");
                    self.scheduleOnce(()=>{
                        clickFunc()
                    },1.5)
                } else {
                    cc.vv.gameData.checkAutoPlay(collectButton, clickFunc);
                    collectButton.getComponent(cc.Button).interactable = true
                    collectButton.off("click");
                    collectButton.on("click", async ()=>{
                        collectButton.stopAllActions();
                        clickFunc();
                    });
                }


            })
        })
    },

    showFreeGameWinCoin(num,freeGameNum){
        return new Promise(async (success,failed)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Mermaid_Freespin_OverView)
            this.showWin()
            let showNode = cc.find("show_freeGame_winCoin",this.node)
            showNode.active = true
            // let particle = cc.find("numBg/lizi",showNode)
            // particle.active = false
            let freeGameTime = cc.find("bg/freeGameBg/num",showNode)
            freeGameTime.getComponent(cc.Label).string = freeGameNum
            let showNodeAnimation = showNode.getComponent(cc.Animation)
            showNodeAnimation.play("showFreeGameWinCoin")
            // particle.active = true
            // particle.getComponent(cc.ParticleSystem).resetSystem()
            // this.scheduleOnce(()=>{
            //     particle.active = false
            // },1.5)
            showNodeAnimation.on("finished",()=>{
                showNodeAnimation.off("finished")
                showNodeAnimation.play("popWinIdel")
                let coin = cc.find("numBg/num",showNode)
                this._startAddCoin = true
                Global.doRoallNumEff(coin,Math.floor(num*0.1),num,1,()=>{
                    this._startAddCoin = false
                },null,0,true);
                let collectButton = cc.find("bg/collectBtn",showNode)
                let self = this;
                let clickFunc = async ()=>{
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.click)
                    collectButton.getComponent(cc.Button).interactable = false
                    if(self._startAddCoin){
                        self._startAddCoin = false
                        coin.stopAllActions()
                        let winCoinLabel = coin.getComponent(cc.Label)
                        winCoinLabel.string = Global.FormatNumToComma(num)
                        await self.awaitTime(0.2)
                    }
                    showNodeAnimation.play("hideFreeGameWinCoin")
                    showNodeAnimation.on("finished",()=>{
                        showNodeAnimation.off("finished")
                        showNode.active = false
                        self.hideWin(()=>{
                            success()
                        })
                    })
                };
                cc.vv.gameData.checkAutoPlay(collectButton, clickFunc);
                collectButton.getComponent(cc.Button).interactable = true
                collectButton.off("click");
                collectButton.on("click", async ()=>{
                    collectButton.stopAllActions();
                    clickFunc();
                });
            })
        })
    },

