    showBonusSelect(){
        return new Promise(async (success,failed)=>{
            Global.SlotsSoundMgr.stopBgm();
            this.showWin()
            this._bonusSelectSuccess = success
            let showNode = cc.find("show_bonus_select",this.node)
            showNode.active = true
            showNode.opacity = 255
            showNode.scale = 1
            this._hailuoList = []
            let self = this;
            let clickFunc = async (i)=>{
                this._hailuoList[0].stopAllActions();
                for (let j = 0; j < this._hailuoList.length; j++) {
                    this._hailuoList[j].getComponent(cc.Button).interactable = false
                }
                let req = {c: MsgId.SLOT_SUBGAME_DATA};
                req.uid = Global.playerData.uid;
                req.gameid = cc.vv.gameData._gameId;
                req.data = {};
                req.data.rtype = 2;
                req.data.choiceId = i+1;
                cc.vv.NetManager.send(req);
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Mermaid_Click_HaiLuo)
            };
            for (let i = 0; i < 3; i++) {
                let hailuo = cc.find("hailuo"+(i+1),showNode)
                this._hailuoList.push(hailuo)
                hailuo.off("click")
                hailuo.getComponent(cc.Button).interactable = true
                hailuo.on("click",()=>{
                    clickFunc(i)
                })
                // cc.find("hailuoBg/hailuoSG",hailuo).active = true
                cc.find("hailuoBg/num",hailuo).color = this._cfg.normalColor
                cc.find("hailuoBg",hailuo).color = this._cfg.normalColor
                cc.find("hailuoBg",hailuo).getComponent(cc.Animation).play("hailuoIdel")
                cc.find("hailuoBg/num",hailuo).active = false
            }
            // 默认选第一个
            cc.vv.gameData.checkAutoPlay(this._hailuoList[0], function () {
                clickFunc(0)
            });
        })
    },

    async onSelectBonus(index,num,bubbleGame){
        let numList = [15,20,30]
        for (let i = 0; i < numList.length; i++) {
            if(numList[i] == num){
                numList.splice(i,1)
                break
            }
        }
        for (let i = 0; i < this._hailuoList.length; i++) {
            const hailuo = this._hailuoList[i]
            if(i === index - 1){  //选中的海螺
                cc.find("hailuoBg/num",hailuo).active = true
                cc.find("hailuoBg/num",hailuo).getComponent(cc.Label).string = num
                let hailuodianji = cc.find("hailuoBg/hailuodianji",hailuo)
                hailuodianji.active = true
                let dianjiAnimation = hailuodianji.getComponent(cc.Animation)
                dianjiAnimation.play("hailuodianji")
                dianjiAnimation.on("finished",()=>{
                    hailuodianji.active = false
                    dianjiAnimation.off("finished")
                })
            }else{
                let tempIndex = Global.random(0,numList.length - 1)
                let numNode = cc.find("hailuoBg/num",hailuo)
                numNode.active = true
                let hailuoBg = cc.find("hailuoBg",hailuo)
                numNode.getComponent(cc.Label).string = numList[tempIndex]
                numList.splice(tempIndex,1)
                numNode.color = this._cfg.grayColor
                hailuoBg.color = this._cfg.grayColor
            }
            cc.find("hailuoBg",hailuo).getComponent(cc.Animation).stop()
            cc.find("hailuoBg",hailuo).y = 0
            // cc.find("hailuoBg/hailuoSG",hailuo).active = false
        }
        await this.awaitTime(2)
        let showNode = cc.find("show_bonus_select",this.node)
        cc.tween(showNode).parallel(cc.tween().to(0.3,{scale:0}),cc.tween().to(0.3,{opacity:0})).call(()=>{
            this.hideWin(()=>{
                if(this._bonusSelectSuccess){
                    this._bonusSelectSuccess()
                    this._bonusSelectSuccess = null
                }
                cc.vv.gameData.getPickGame().startPickGame(num,bubbleGame.winCoin,bubbleGame.results)
            })
        }).start()
    },

    showJackpotWinCoin(num,jpid){
        return new Promise(async (success,failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Mermaid_JackpotView)
            this.showWin()
            let showNode = cc.find("show_jackpot_winCoin",this.node)
            showNode.active = true
            let meirenyu = cc.find("Mermaid_guochang",showNode)
            meirenyu.active = true
            let meirenyuSp = meirenyu.getComponent(sp.Skeleton)
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Mermaid_Jp_yu_shengQi)
            meirenyuSp.setAnimation(0,"skill",false)
            // meirenyuSp.addAnimation(0,"guochang3over",false)
            cc.find("numBg/title",showNode).getComponent("ImgSwitchCmp").setIndex(jpid-1);
            let coin = cc.find("numBg/num",showNode)
            coin.getComponent(cc.Label).string = ""
            let showNodeAnimation = showNode.getComponent(cc.Animation)
            showNodeAnimation.play("showJackpotWinCoin")
            this.scheduleOnce(()=>{
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.Mermaid_JackPotWinCoins)
                this._startAddCoin = true
                Global.doRoallNumEff(coin,Math.floor(num*0.1),num,2,()=>{
                    this._startAddCoin = false
                    Global.SlotsSoundMgr.stopEffectByName(Global.SlotsSoundMgr.Mermaid_JackPotWinCoins)
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.Mermaid_JackPotWinCoins_end)
                },null,0,true);
            },2.1)
            this.scheduleOnce(()=>{
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_Mermaid_Jp_yu_FeiWen)
            },1.66)
            showNodeAnimation.on("finished",async ()=>{
                showNodeAnimation.off("finished")
                showNodeAnimation.play("idelJackpotWinCoin")
                await this.awaitTime(2)
                showNodeAnimation.play("hideJackpotWinCoin")
                showNodeAnimation.on("finished",async ()=>{
                    showNodeAnimation.off("finished")
                    this.hideWin(()=>{
                        showNode.active = false
                        success()
                    })
                })
            })
        })
    },

